package com.curso.services;
import com.curso.domains.Usuario;import com.curso.repositories.UsuarioRepository;import com.curso.services.exceptions.ObjectNotFoundException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;
@Service public class UsuarioAtualService{private final UsuarioRepository repo;public UsuarioAtualService(UsuarioRepository r){repo=r;}public Usuario obter(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return repo.findByEmailIgnoreCase(email).orElseThrow(()->new ObjectNotFoundException("Usuário autenticado não encontrado"));} public Usuario bloquear(){return repo.bloquear(obter().getId()).orElseThrow(()->new ObjectNotFoundException("Usuário não encontrado"));}}
